using System;
using System.Threading;
using Pretzel.Data;
using UnityEngine;

public static class PretzelDataSetup
{
    // The key is split in two arrays and combined at runtime. This only defeats a plain search of the build.
    private static readonly byte[] PartA = new byte[] { 0xF8, 0xC7, 0xD5, 0x05, 0x5E, 0xF1, 0x4A, 0xDD, 0x21, 0x3B, 0xBE, 0xD7, 0xEE, 0xAA, 0x98, 0xAE, 0x4A, 0x54, 0xB6, 0x14, 0x94, 0x4D, 0xCC, 0x5C, 0x86, 0x05, 0xA0, 0x95, 0x6F, 0x43, 0x10, 0xE2 };
    private static readonly byte[] PartB = new byte[] { 0xD3, 0xBF, 0x5E, 0xCD, 0x28, 0x76, 0xDD, 0x22, 0x33, 0x36, 0xB7, 0x85, 0xDD, 0xCB, 0x74, 0x41, 0x1E, 0x2F, 0xF1, 0x04, 0x57, 0xF0, 0x80, 0xA4, 0x0E, 0x06, 0xF8, 0xCD, 0x1F, 0x04, 0x97, 0x9F };

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]
    private static void Register()
    {
        EncryptionKeys.Provider = BuildKeys;
    }

    private static EncryptionKeys BuildKeys()
    {
        byte[] key = new byte[PartA.Length];
